1502: /* 拉取全部目标的安全边际指标，填充 MARGIN；当日缓存避免每次 10s 刷新都重算 */
1503: function loadMarginMetrics(force) {
1504:   if (!CFG || !TARGETS.length) return Promise.resolve(0);
1505:   const params = (CFG.margin) || {};
1506:   const today = new Date().toISOString().slice(0, 10);
1507:   if (!force) {
1508:     try {
1509:       const raw = localStorage.getItem(MARGIN_CACHE_KEY);
1510:       if (raw) {
1511:         const c = JSON.parse(raw);
1512:         if (c && c.date === today && c.items && Object.keys(c.items).length) {
1513:           Object.keys(c.items).forEach(k => { MARGIN[k] = c.items[k]; });
1514:           // 缓存命中也要校验完整性：目标池可能新增了标的（如新入池的替补），
1515:           // 当日缓存里没有它的指标，若直接 return 会让新标的天天报「缺安全边际指标」。
1516:           // 这里只为「缓存中缺失」的标的补齐，已缓存的不重拉（仍省请求）。
1517:           const missing = TARGETS.filter(t => {
1518:             const sym = t.symbol || (t.code + (String(secidOf(t.code))[0] === '1' ? '.SH' : '.SZ'));
1519:             return !MARGIN[sym] && !MARGIN[t.code];
1520:           });
1521:           if (!missing.length) return Promise.resolve(marginCount());
1522:           return Promise.all(missing.map(t =>
1523:             _mComputeOne(t, params).then(it => {
1524:               const sym = t.symbol || (t.code + (String(secidOf(t.code))[0] === '1' ? '.SH' : '.SZ'));
1525:               MARGIN[sym] = it;
1526:               return it;
1527:             }).catch(() => null)
